const body = $json.body ?? $json;
const dealId = String(body.dealId ?? '').trim();
const periodStart = String(body.periodStart ?? '').trim();
const periodEnd = String(body.periodEnd ?? '').trim();
const source = String(body.source ?? body.leadSource ?? '').trim();
const marketingChannel = String(body.marketingChannel ?? body.channel ?? '').trim();
const campaign = String(body.campaign ?? body.campaignName ?? '').trim();
if (!periodStart || !periodEnd) throw new Error('periodStart and periodEnd are required');
if (new Date(periodStart).getTime() > new Date(periodEnd).getTime()) throw new Error('periodStart must be before periodEnd');
return [{ json: { dealId, periodStart, periodEnd, source, marketingChannel, campaign, requestedAt: new Date().toISOString() } }];

const ctx = $json.data ?? $json;
const records = Array.isArray(ctx.records) ? ctx.records : (Array.isArray(ctx.deals) ? ctx.deals : []);
const valid = records.filter(r => r && (r.leadSource || r.source || r.marketingChannel || r.channel || r.campaign));
if (!valid.length) throw new Error('No valid lead source/channel performance data available for the requested period');
return [{ json: { records: valid, periodStart: $('Normalize Source Performance Request').first().json.periodStart, periodEnd: $('Normalize Source Performance Request').first().json.periodEnd } }];

const records = $json.records;
const buckets = new Map();
const num = v => Number.isFinite(Number(v)) ? Number(v) : 0;
for (const r of records) {
  const key = [r.leadSource ?? r.source ?? 'unknown', r.marketingChannel ?? r.channel ?? 'unknown', r.campaign ?? 'unknown', r.dispositionChannel ?? 'unknown'].map(String).join('|');
  if (!buckets.has(key)) buckets.set(key, { leadSource: r.leadSource ?? r.source ?? 'unknown', marketingChannel: r.marketingChannel ?? r.channel ?? 'unknown', campaign: r.campaign ?? 'unknown', dispositionChannel: r.dispositionChannel ?? 'unknown', leads: 0, contracts: 0, closedDeals: 0, grossRevenue: 0, netProfit: 0, spend: 0 });
  const b = buckets.get(key);
  b.leads += num(r.leads ?? r.leadCount ?? (r.isLead ? 1 : 0));
  b.contracts += num(r.contracts ?? r.contractCount ?? (r.contractSigned ? 1 : 0));
  b.closedDeals += num(r.closedDeals ?? r.closedDealCount ?? (r.closed ? 1 : 0));
  b.grossRevenue += num(r.grossRevenue);
  b.netProfit += num(r.netProfit);
  b.spend += num(r.spend ?? r.sourceSpend ?? r.campaignSpend);
}
const rows = [...buckets.values()].map(b => ({ ...b, costPerLead: b.leads ? b.spend / b.leads : 0, costPerContract: b.contracts ? b.spend / b.contracts : 0, costPerClosedDeal: b.closedDeals ? b.spend / b.closedDeals : 0, leadToContractRate: b.leads ? b.contracts / b.leads : 0, contractToCloseRate: b.contracts ? b.closedDeals / b.contracts : 0, leadToCloseRate: b.leads ? b.closedDeals / b.leads : 0, roi: b.spend ? (b.netProfit - b.spend) / b.spend : null, profitMultiple: b.spend ? b.netProfit / b.spend : null }));
const totals = rows.reduce((a, b) => { for (const k of ['leads','contracts','closedDeals','grossRevenue','netProfit','spend']) a[k] += b[k]; return a; }, { leads:0, contracts:0, closedDeals:0, grossRevenue:0, netProfit:0, spend:0 });
totals.costPerLead = totals.leads ? totals.spend / totals.leads : 0;
totals.costPerContract = totals.contracts ? totals.spend / totals.contracts : 0;
totals.costPerClosedDeal = totals.closedDeals ? totals.spend / totals.closedDeals : 0;
totals.leadToContractRate = totals.leads ? totals.contracts / totals.leads : 0;
totals.contractToCloseRate = totals.contracts ? totals.closedDeals / totals.contracts : 0;
totals.leadToCloseRate = totals.leads ? totals.closedDeals / totals.leads : 0;
totals.roi = totals.spend ? (totals.netProfit - totals.spend) / totals.spend : null;
totals.profitMultiple = totals.spend ? totals.netProfit / totals.spend : null;
return [{ json: { periodStart: $json.periodStart, periodEnd: $json.periodEnd, aggregation: rows, totals, recordCount: records.length, aggregatedAt: new Date().toISOString() } }];
